import{_ as o,o as u,c as q,ag as e}from"./chunks/framework.CAXxHpAX.js";const l=JSON.parse('{"title":"金刚经7分-无有定法","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经7分-无有定法.md","filePath":"60-原文段落/金刚经7分-无有定法.md","lastUpdated":1778155802000}'),a={name:"60-原文段落/金刚经7分-无有定法.md"};function r(p,t,_,s,n,c){return u(),q("div",null,[...t[0]||(t[0]=[e('<h1 id="金刚经7分-无有定法" tabindex="-1">金刚经7分-无有定法 <a class="header-anchor" href="#金刚经7分-无有定法" aria-label="Permalink to &quot;金刚经7分-无有定法&quot;">​</a></h1><blockquote><p>来源：<a href="/01-Raw-Sources/7了空居士讲《金刚经》-第七分无得无说分20161014">7了空居士讲《金刚经》-第七分无得无说分20161014</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>无有定法名阿耨多罗三藐三菩提，亦无有定法如来可说。</strong></p><p>须菩提说：按照我自己的理解，对佛祖你所说的一切法的理解——没有一个固定的做法叫作&quot;阿耨多罗三藐三菩提&quot;。其实&quot;是名阿耨多罗三藐三菩提&quot;，就是说你能够悟到一切法都是平等的。平等在什么程度啊？&quot;缘起性空&quot;啊，它不是指一个固定的方法，是悟到了这种道理的人他就叫作证得&quot;阿耨多罗三藐三菩提&quot;。</p><p>但世尊又怕我们听不清楚，说&quot;以无我无人无众生无寿者修一切善法，则得阿耨多罗三藐三菩提&quot;。这个&quot;一切善法&quot;也是要因地制宜的啊，是不是啊？你说到极处，它也没有一个绝对标准，你必须遇到那个事情，具体问题具体分析，因此也还是没有一个定法。</p><p>说到极处确实还是没有固定，还是要具体问题具体分析。</p><p><strong>何以故？如来所说法，皆不可取，不可说，非法，非非法。</strong></p><p>这个&quot;不可取&quot;的意思就是不能照搬硬套，如来说的这些都是针对性的，你们如果换一个场合，换一个时间，可能就不能这么套进去了。就是说&quot;不可取&quot;的意思就是不能落入教条主义，不要说&quot;取&quot;过来，就来&quot;套&quot;进去用，不能这么做。&quot;皆不可取，不可说&quot;，&quot;说&quot;的意思就是你依样画葫芦地说给别人去，其实&quot;取&quot;就是自己听过来去照搬硬套，&quot;说&quot;就是你用这个方法去教别人去教条主义，是这个意思。</p><p>&quot;非法&quot;直接翻译过来就是&quot;不是法&quot;，&quot;非非法&quot;就&quot;不是不是法&quot;。&quot;非法&quot;就是说如来所说的这些道理，不是一个绝对的道理，它是相对的，它是针对某一个具体的事情是有效的，对另外一个事情也许是无效的，这就是&quot;非法&quot;的真实义。&quot;非非法&quot;，就是说，否定之否定，就是&quot;也不是&quot;——前面说&quot;非法&quot;就是&quot;不是方法&quot;——&quot;非非法&quot;，不是不是方法，就是说：你也不能倒过来，就觉得一定是有用的，也就是说，你不能认为这个方法一定是有用的，或者是一定是没用的，不能这么认为，而是说它是具体的应用，有针对性的那个就有用的，如果偏离了这个方面，他就没有用了啊。</p><p><strong>所以者何？一切贤圣皆以无为法而有差别。</strong></p><p>这些开悟的人有智慧的人，他们为人处世啊，都是&quot;以无为法而有差别&quot;。这里最关键就是&quot;无为法&quot;。什么是无为法？就是不妄为、不主观臆断、不武断啊。就是做什么事情，&quot;无为法&quot;，就是说不要有任何成见，你都要按照客观实际情况去&quot;差别&quot;，&quot;差别&quot;就是错落高低嘛，分门别类嘛，其实就是依实际情况去具体问题具体分析或者是去因地制宜啊，而不是教条主义或者什么照搬硬套等等本本主义啊等等。一定要按照实际情况去分析去应用。</p>',12)])])}const i=o(a,[["render",r]]);export{l as __pageData,i as default};
